if __name__ == '__main__':
    import json, requests, time

    API_URL = "https://context-tree-ai.preview.emergentagent.com"
    messages = LARGE_CONVERSATION

    total_chars = sum(len(m['text']) for m in messages)
    print(f"Conversation stats:")
    print(f"  Messages: {len(messages)}")
    print(f"  Total characters: {total_chars:,}")
    print(f"  Approx raw tokens: ~{total_chars // 4:,}")
    print(f"  Expected reduction at 4K budget: ~{max(0, int((1 - 4000/(total_chars//4))*100))}%")

    print(f"\nIndexing conversation 'fintech-data-platform'...")
    resp = requests.post(f"{API_URL}/api/index", json={
        "conversation_id": "fintech-data-platform",
        "messages": messages
    }, timeout=60)
    print(f"Response: {resp.json()}")

    print("Polling for completion...")
    for i in range(90):
        time.sleep(5)
        status = requests.get(f"{API_URL}/api/status/fintech-data-platform").json()
        print(f"  [{i+1}] {status.get('status')} - {status.get('progress','')[:60]}")
        if status.get('status') in ('indexed', 'error'):
            break

    if status.get('status') == 'indexed':
        s = status.get('stats', {})
        raw = s.get('estimated_raw_tokens', 0)
        reduction = max(0, int((1 - 4000/max(1, raw))*100))
        print(f"\n{'='*50}")
        print(f"INDEXED SUCCESSFULLY!")
        print(f"  Messages: {s.get('total_messages')}")
        print(f"  Topics:   {s.get('total_topics')}")
        print(f"  Chunks:   {s.get('total_chunks')}")
        print(f"  Raw tokens: {raw:,}")
        print(f"  Max reduction at 4K budget: {reduction}%")
        print(f"{'='*50}")
    else:
        print(f"Indexing failed: {status}")
